"use strict";(self.webpackChunkmindstack=self.webpackChunkmindstack||[]).push([["8381"],{2658(e,n,i){i.r(n),i.d(n,{metadata:()=>t,default:()=>p,frontMatter:()=>a,contentTitle:()=>s,toc:()=>c,assets:()=>l});var t=JSON.parse('{"id":"networks/optical-networking","title":"Optical Networking","description":"Optical networking carries data as light pulses through fiber. Understanding SONET/SDH history, DWDM technology, and coherent optics is essential for anyone working with high-speed transport networks.","source":"@site/docs/networks/75-optical-networking.md","sourceDirName":"networks","slug":"/networks/optical-networking","permalink":"/Mindstack/docs/networks/optical-networking","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":75,"frontMatter":{"title":"Optical Networking","sidebar_label":"Optical Networking","sidebar_position":75},"sidebar":"networkSidebar","previous":{"title":"Service Provider","permalink":"/Mindstack/docs/networks/service-provider-technologies"},"next":{"title":"IPv6 Deployment","permalink":"/Mindstack/docs/networks/ipv6-deployment-guide"}}'),r=i(4848),o=i(8453);let a={title:"Optical Networking",sidebar_label:"Optical Networking",sidebar_position:75},s="Optical Networking",l={},c=[{value:"Why Optical",id:"why-optical",level:2},{value:"Fiber Types",id:"fiber-types",level:2},{value:"Single-Mode Fiber (SMF)",id:"single-mode-fiber-smf",level:3},{value:"Multi-Mode Fiber (MMF)",id:"multi-mode-fiber-mmf",level:3},{value:"SONET and SDH (Legacy)",id:"sonet-and-sdh-legacy",level:2},{value:"DWDM \u2014 Dense Wavelength Division Multiplexing",id:"dwdm--dense-wavelength-division-multiplexing",level:2},{value:"Coherent Optics",id:"coherent-optics",level:2},{value:"OTN \u2014 Optical Transport Network (ITU-T G.709)",id:"otn--optical-transport-network-itu-t-g709",level:2},{value:"Fiber Troubleshooting",id:"fiber-troubleshooting",level:2},{value:"Tips",id:"tips",level:2},{value:"Summary",id:"summary",level:2}];function d(e){let n={code:"code",h1:"h1",h2:"h2",h3:"h3",header:"header",hr:"hr",li:"li",p:"p",pre:"pre",ul:"ul",...(0,o.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n.header,{children:(0,r.jsx)(n.h1,{id:"optical-networking",children:"Optical Networking"})}),"\n",(0,r.jsx)(n.p,{children:"Optical networking carries data as light pulses through fiber. Understanding SONET/SDH history, DWDM technology, and coherent optics is essential for anyone working with high-speed transport networks."}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"why-optical",children:"Why Optical"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"Electrical vs Optical signal comparison:\n  Copper (electrical):\n    Attenuation: severe over distance (signal lost to resistance, skin effect)\n    Bandwidth: limited by parasitic capacitance (frequency ceiling)\n    Interference: susceptible to electromagnetic interference (EMI)\n    Max practical: Cat8 \u2192 40 Gbps at 30m; coaxial \u2192 10 Gbps at short distances\n\n  Fiber (optical):\n    Attenuation: very low (0.2 dB/km for SMF vs 100s dB/km for copper at high frequency)\n    Bandwidth: theoretically unlimited (carrier frequency ~200 THz)\n    Interference: immune to EMI; no ground loops; no crosstalk between fibers\n    Distance: 80\u2013160 km between amplifiers without regeneration; 1000s km with amplifiers\n    Practical: 400 Gbps per wavelength; 100+ wavelengths per fiber \u2192 Tbps per strand\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"fiber-types",children:"Fiber Types"}),"\n",(0,r.jsx)(n.h3,{id:"single-mode-fiber-smf",children:"Single-Mode Fiber (SMF)"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"Core diameter: 8-10 \xb5m (very narrow \u2014 only one mode of light travels)\nCladding: 125 \xb5m (standard)\nWavelength: 1310 nm or 1550 nm (infrared)\nAttenuation: 0.2-0.4 dB/km at 1550 nm (very low)\nBandwidth: effectively unlimited for practical purposes\nDistance: up to 160 km between amplifiers; 40 km+ without amplification\n\nTypes of SMF:\n  G.652 (Standard SMF): most common; OS1 (indoor), OS2 (outdoor)\n  G.653 (Dispersion-Shifted): shifted dispersion minimum to 1550 nm; problematic for DWDM\n  G.654 (Ultra-Low Loss): submarine cables; 0.17 dB/km\n  G.655 (Non-Zero Dispersion-Shifted): DWDM optimized; used in long-haul\n  G.656 (Non-Zero DSF for wideband): supports C+L band DWDM\n\nUse for: all long-distance (> 2 km), datacenter interconnect, WAN\n\nConnectors for SMF:\n  SC (square connector): snap-in; widely used in telco\n  LC (lucent connector): smaller; most common in datacenter SFPs\n  FC (threaded connector): secure; used in lab/test equipment\n  MPO/MTP: 12 or 24 fibers in one connector; high-density datacenter\n"})}),"\n",(0,r.jsx)(n.h3,{id:"multi-mode-fiber-mmf",children:"Multi-Mode Fiber (MMF)"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"Core diameter: 50 \xb5m or 62.5 \xb5m (larger \u2014 multiple modes of light travel)\nCladding: 125 \xb5m (same as SMF)\nWavelength: 850 nm or 1300 nm\nAttenuation: 2-3 dB/km (higher than SMF)\nDistance: 300-400m at 10G; 100m at 40/100G (limited by modal dispersion)\nBandwidth: limited by modal dispersion (different modes travel different paths \u2192 arrive at different times)\n\nTypes (OM = Optical Multimode):\n  OM1: 62.5 \xb5m core; 200 MHz\xb7km bandwidth; legacy\n  OM2: 50 \xb5m; 500 MHz\xb7km; older deployments\n  OM3 (Laser-Optimized): 50 \xb5m; 2000 MHz\xb7km; 10G up to 300m\n  OM4 (Laser-Optimized): 50 \xb5m; 4700 MHz\xb7km; 40/100G up to 150m\n  OM5 (Wideband MMF): 50 \xb5m; supports 4 wavelengths (850, 877, 906, 953 nm); 100G+\n\nUse for: intra-datacenter short runs, building riser, within rack rows\n  Where SMF is overkill for short distances; cheaper transceivers (VCSEL lasers vs DFB)\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"sonet-and-sdh-legacy",children:"SONET and SDH (Legacy)"}),"\n",(0,r.jsx)(n.p,{children:"SONET (Synchronous Optical Networking, ANSI) and SDH (Synchronous Digital Hierarchy, ITU-T) were the dominant transport standards from the 1980s through the 2000s."}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"Design philosophy:\n  Synchronous: all clocks synchronized to a common reference (Stratum hierarchy)\n  TDM-based: fixed timeslots for each circuit; guaranteed bandwidth\n  Operations overhead: rich OAM (Operations, Administration, Maintenance) built in\n  Protection switching: 50ms failover via APS (Automatic Protection Switching)\n\nSONET hierarchy (North America):\n  STS-1 (OC-1):   51.84 Mbps    \u2014 base signal\n  OC-3:           155.52 Mbps   \u2014 3 \xd7 STS-1\n  OC-12:          622.08 Mbps   \u2014 12 \xd7 STS-1\n  OC-48:          2.488 Gbps    \u2014 48 \xd7 STS-1\n  OC-192:         9.953 Gbps    \u2014 192 \xd7 STS-1\n  OC-768:         39.813 Gbps   \u2014 768 \xd7 STS-1\n\nSDH hierarchy (international):\n  STM-1:  155.52 Mbps   (= OC-3)\n  STM-4:  622.08 Mbps   (= OC-12)\n  STM-16: 2.488 Gbps    (= OC-48)\n  STM-64: 9.953 Gbps    (= OC-192)\n\nSONET frame structure:\n  Each STS-1 frame: 9 rows \xd7 90 columns = 810 bytes; sent 8000 times/second\n  \u2192 810 \xd7 8 \xd7 8000 = 51.84 Mbps\n  Overhead: 9 rows \xd7 3 columns (27 bytes) = transport overhead\n  Payload: 9 rows \xd7 87 columns (783 bytes) = SPE (Synchronous Payload Envelope)\n\nSONET/SDH today:\n  Legacy: still in service on old carrier networks for leased lines and TDM transport\n  Being replaced by: OTN (Optical Transport Network) + DWDM Ethernet\n  Enterprise: rarely seen; ISPs migrating to OTN/Ethernet transport\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"dwdm--dense-wavelength-division-multiplexing",children:"DWDM \u2014 Dense Wavelength Division Multiplexing"}),"\n",(0,r.jsx)(n.p,{children:"DWDM is the technology that puts terabits of data on a single fiber strand by transmitting on many different wavelengths simultaneously."}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"WDM concept:\n  Each wavelength (color) carries an independent signal\n  Combine multiple wavelengths on one fiber via optical multiplexer\n  Separate at the other end via optical demultiplexer\n  Total capacity = wavelengths \xd7 capacity-per-wavelength\n\nCWDM (Coarse WDM):\n  Wavelengths: 18 channels from 1270 nm to 1610 nm (20 nm spacing)\n  No optical amplification required (low cost)\n  Max distance: ~80 km\n  Use: metro access; short-haul; cheaper than DWDM\n\nDWDM (Dense WDM):\n  Wavelengths: up to 96 channels on C-band (1530-1565 nm) at 50 GHz spacing\n              Up to 160 channels at 25 GHz spacing\n  With L-band: doubles channel count (add 1565-1625 nm band)\n  Each wavelength: today 100G, 200G, 400G (coherent optics)\n  Total capacity: 96 \xd7 400G = 38.4 Tbps on a single fiber pair\n\nEDFA (Erbium-Doped Fiber Amplifier):\n  Amplifies all DWDM wavelengths simultaneously (no OEO conversion needed)\n  Operating range: 1530-1565 nm (C-band) \u2014 same band as DWDM\n  Amplification: +20 to +30 dB gain; repeat every 80-100 km\n  Limitation: amplifies noise too; limited span count before regeneration\n\nROADM (Reconfigurable Optical Add/Drop Multiplexer):\n  Add or drop individual wavelengths at intermediate nodes\n  Remotely reconfigurable (software-defined wavelength routing)\n  Degree: how many directions fiber enters/exits the ROADM\n  CDC (Colorless, Directionless, Contentionless): any wavelength to any port \u2014 flexible\n  Enables: optical circuit provisioning without visiting each intermediate site\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"coherent-optics",children:"Coherent Optics"}),"\n",(0,r.jsx)(n.p,{children:"Modern DWDM uses coherent detection \u2014 the receiver tracks phase and amplitude, enabling dramatically higher spectral efficiency."}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"Traditional (Direct Detection):\n  Receiver measures light intensity only\n  On/Off Keying (OOK): 1 = light, 0 = dark\n  Limited to 10G-40G per wavelength before dispersion limits capacity\n\nCoherent (Phase Detection):\n  Receiver tracks: amplitude (I) and phase (Q) of the optical carrier\n  Modulation formats:\n    QPSK: 2 bits per symbol (2 polarizations \xd7 2 bits = 4 bits/symbol) \u2192 100G at 50 GHz\n    16-QAM: 4 bits per symbol (2 pol \xd7 4 bits = 8 bits/symbol) \u2192 200G at 50 GHz\n    64-QAM: 6 bits per symbol \u2192 400G at 50 GHz\n    256-QAM: 8 bits per symbol \u2192 800G at 50 GHz\n\nDP (Dual Polarization):\n  Light has two orthogonal polarization states (X and Y)\n  Modulate both independently \u2192 double capacity\n  DP-QPSK: most robust (100G, long haul)\n  DP-16QAM: higher capacity (200G), shorter reach\n  DP-64QAM: 400G, metro/short-haul\n\nDSP (Digital Signal Processor):\n  Coherent systems include powerful ASIC DSP\n  Compensates: chromatic dispersion (CD), polarization mode dispersion (PMD), OSNR\n  Makes long-haul 100G viable without inline dispersion compensation modules\n\nCurrent deployed rates:\n  100G: DP-QPSK; deployed since 2010; backbone standard\n  200G: DP-16QAM; metro/regional standard\n  400G: DP-16QAM or DP-64QAM; being widely deployed\n  800G: DP-64QAM or DP-256QAM; emerging; research labs at 1.6T\n\nOpen ROADM / Open Line System:\n  Disaggregate DWDM: use any vendor's transponders with any vendor's ROADM\n  OpenConfig for optical: standard data models for coherent transceivers\n  Avoids vendor lock-in in optical layer (historically very proprietary)\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"otn--optical-transport-network-itu-t-g709",children:"OTN \u2014 Optical Transport Network (ITU-T G.709)"}),"\n",(0,r.jsx)(n.p,{children:'OTN is the modern replacement for SONET/SDH \u2014 provides an "optical wrapper" for client signals.'}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"OTN frame hierarchy:\n  OTU1:  2.66 Gbps  (carries OC-48/STM-16)\n  OTU2:  10.7 Gbps  (carries OC-192/STM-64/10GE)\n  OTU3:  43.0 Gbps  (carries OC-768/STM-256/40GE)\n  OTU4:  112 Gbps   (carries 100GE \u2014 most widely deployed today)\n  OTUCn: n \xd7 100G   (for 200G, 400G, 800G signals)\n\nOTN overhead:\n  FEC (Forward Error Correction): G.709 includes 7% overhead for FEC\n    Corrects bit errors introduced by optical noise\n    Hard FEC: Reed-Solomon (7% overhead)\n    Soft FEC / Turbo FEC / LDPC: 20-25% overhead; much better performance\n    Modern coherent systems: soft FEC enables lower OSNR operation \u2192 longer reach\n\n  OAM: rich overhead like SONET \u2014 performance monitoring, alarm propagation, TCM\n  TCM (Tandem Connection Monitoring): end-to-end and segment monitoring\n\nOTN benefits over SONET:\n  Client-agnostic: wrap Ethernet, Fibre Channel, SDH \u2014 anything\n  Non-synchronous: client clocks not required to be synchronous to network\n  FEC: built-in; significantly extends reach vs SDH\n  Scalable: OTUCn \u2192 arbitrary capacity multiples\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"fiber-troubleshooting",children:"Fiber Troubleshooting"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"OTDR (Optical Time Domain Reflectometer):\n  Sends pulse of light; measures reflections and backscatter vs time\n  Time \u2192 distance (speed of light in fiber: ~200,000 km/s)\n  Shows: connector loss, splice loss, bends, fiber breaks, fiber end\n  Can locate a fiber break to within 1 meter over 100 km\n\nReading an OTDR trace:\n  Flat slope: healthy fiber (0.2 dB/km for SMF)\n  Step down: splice or connector (loss point)\n  Large reflection peak: mechanical connector (Fresnel reflection)\n  End of fiber: large step down to noise floor (Fresnel reflection at end + no more backscatter)\n  Sudden drop to noise floor: fiber break (no more backscatter beyond break)\n\nOptical power meter:\n  Measures received power in dBm\n  Compare to launch power \u2192 calculate insertion loss\n  Insertion loss budget: launch power - minimum sensitivity = max allowed loss\n  Example: QSFP28 100G LR: launch +3 dBm; sensitivity -10 dBm; budget = 13 dB (\u224810 km)\n\nOptical cleaning:\n  Dirty connectors: #1 cause of fiber problems\n  Always clean with fiber optic cleaning tools before connecting\n  Inspect with fiber inspection scope (200\xd7-400\xd7) before and after cleaning\n  Connector endface damage: scratches, chips \u2192 must be repolished or connector replaced\n\nOSNR (Optical Signal-to-Noise Ratio):\n  Signal power vs amplified spontaneous emission (ASE) noise from EDFAs\n  Minimum OSNR required per modulation format:\n    DP-QPSK (100G): ~15 dB OSNR\n    DP-16QAM (200G): ~19 dB OSNR\n    DP-64QAM (400G): ~26 dB OSNR\n  OSNR degrades with each EDFA span; limits maximum system reach\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"tips",children:"Tips"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"Always clean fiber connectors before connecting \u2014 a fingerprint on an LC connector attenuates the signal by 3\u201310 dB (the equivalent of several kilometers of additional fiber)."}),"\n",(0,r.jsx)(n.li,{children:"Know your loss budget before deploying: (launch power dBm) \u2212 (sensitivity dBm) = max dB of insertion loss the link can tolerate. Measure actual loss before commissioning."}),"\n",(0,r.jsx)(n.li,{children:"OM3/OM4 multimode is fine for intra-DC runs under 100m; use SMF for anything crossing between buildings or exceeding 100-400m \u2014 the transceiver cost difference is small compared to fiber replacement later."}),"\n",(0,r.jsx)(n.li,{children:"Coherent 400G transceivers are software-tunable \u2014 the same QSFP-DD hardware can run at 100G, 200G, or 400G by changing the modulation format in software (trading reach for speed)."}),"\n",(0,r.jsx)(n.li,{children:"OSNR margin: always design with 3-4 dB OSNR margin beyond the minimum \u2014 this accounts for aging components, seasonal temperature effects, and unexpected added spans."}),"\n"]}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"summary",children:"Summary"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"SMF (8-10\xb5m core) for long distances (>2km); MMF (50\xb5m) for intra-DC short runs (< 400m) \u2014 SMF supports DWDM, MMF does not."}),"\n",(0,r.jsx)(n.li,{children:"SONET/SDH (TDM-based, synchronous) is the legacy standard; OTN (client-agnostic wrapper with FEC) is the modern replacement; both run over DWDM wavelengths."}),"\n",(0,r.jsx)(n.li,{children:"DWDM multiplexes 40-160 wavelengths per fiber strand; EDFA amplifies all wavelengths simultaneously; ROADM enables remote wavelength routing."}),"\n",(0,r.jsx)(n.li,{children:"Coherent optics (DP-QPSK, DP-16QAM, DP-64QAM) enables 100G-400G per wavelength by detecting both amplitude and phase \u2014 DSP compensates for dispersion and noise."}),"\n",(0,r.jsx)(n.li,{children:"Total fiber capacity: 96 channels \xd7 400G = 38.4 Tbps per fiber pair \u2014 and more with L-band extension."}),"\n",(0,r.jsx)(n.li,{children:"Dirty connectors and insufficient OSNR margin are the two most common optical network failures \u2014 clean before connecting; measure before commissioning."}),"\n"]})]})}function p(e={}){let{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(d,{...e})}):d(e)}},8453(e,n,i){i.d(n,{R:()=>a,x:()=>s});var t=i(6540);let r={},o=t.createContext(r);function a(e){let n=t.useContext(o);return t.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:a(e.components),t.createElement(o.Provider,{value:n},e.children)}}}]);